#!/usr/bin/env node
/**
 * Create a linked git worktree whose git hooks actually fire.
 *
 * WHY THIS EXISTS. `git worktree add` alone produces a worktree where EVERY git hook is silently
 * skipped, and nothing anywhere reports it.
 *
 *   core.hooksPath is `.husky/_` — a RELATIVE path, resolved from each worktree's own root
 *   `.husky/_` is generated by husky's `prepare` script, and self-ignores via `.husky/_/.gitignore`
 *   → it is neither tracked nor copied into a new worktree, so the path does not resolve
 *   → git skips the hook with no warning, no error, no exit code
 *
 * Measured 2026-08-17: three commits and two pushes were made from a linked worktree on
 * `feat/phase-guard-declaration-contract` (PR #239). Pre-commit and pre-push ran zero times. The
 * push succeeded seconds after `server/node_modules` was deleted, because nothing tried to use it.
 * CI was not the first gate to catch the stale schema-version assertions in that branch — it was
 * the ONLY gate that ran.
 *
 * That worktree was created to isolate work from a concurrent session, which is a pattern this
 * repository uses routinely (`typecheck-committed.js` creates one per push; several plans in
 * `plans/` record doing the same by hand). Every one of those was hookless.
 *
 * MECHANISM. Two steps `git worktree add` does not do:
 *
 *   1. Run husky with cwd set to the new worktree, regenerating `.husky/_` there. This is the
 *      canonical tool doing its own job, not a hand-rolled copy that would drift from the husky
 *      version in the lockfile.
 *   2. Symlink `node_modules` AND `server/node_modules` from the main worktree. The hooks shell
 *      out to `npm --prefix server run …` for the server checks and resolve commitlint from the
 *      ROOT tree, so a worktree missing either fails on the first command. Symlinked rather than
 *      installed for the same reason `typecheck-committed.js` symlinks: a real install costs
 *      minutes, and the dependency tree is identical by construction.
 *
 * SELF-VERIFYING. Wiring hooks and reporting success without checking is how this failure mode
 * survived in the first place, so the last steps assert the linked tree reads clean to
 * `git status` and that `.husky/_/pre-push` exists and is executable, and fail loudly naming the
 * remedy if not. A bootstrap that cannot prove it bootstrapped is the same class of defect it
 * exists to fix.
 *
 * REJECTED: pointing `core.hooksPath` at an absolute path in the main worktree. It would fix
 * resolution for every worktree at once, but `.git/config` is shared, so every linked worktree
 * would then run the MAIN worktree's copy of `.husky/pre-push` — a hook edit on one branch would
 * silently govern pushes from every other branch, and checking out a commit that predates a hook
 * would not change which hook ran.
 *
 * USAGE
 *   node scripts/create-worktree.js <path> <branch> [--from <base>]
 *   npm run worktree:create -- ../repo-featurex feat/x --from origin/main
 *
 * `<branch>` is created when it does not exist (from `--from`, default `HEAD`), and checked out
 * when it does.
 */

// CommonJS: the repository root package.json declares no `type`, and `scripts/` siblings
// (request-renovate-run.js) use require. `server/` is the ESM half; this is not it.
const { execFileSync } = require('node:child_process');
const { existsSync, accessSync, symlinkSync, constants } = require('node:fs');
const path = require('node:path');

/** Run git in the main worktree, returning trimmed stdout. */
function git(args, cwd = process.cwd()) {
  return execFileSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
}

function fail(message) {
  console.error(`\n❌ ${message}\n`);
  process.exit(1);
}

function parseArgs(argv) {
  const positional = [];
  let from = 'HEAD';
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] === '--from') {
      from = argv[i + 1];
      if (!from) fail('--from needs a value (a commit-ish to branch from).');
      i += 1;
    } else {
      positional.push(argv[i]);
    }
  }
  const [target, branch] = positional;
  if (!target || !branch) {
    fail(
      'usage: node scripts/create-worktree.js <path> <branch> [--from <base>]\n' +
        '   eg: npm run worktree:create -- ../claude-prompts-mcp-featurex feat/x --from origin/main'
    );
  }
  return { target, branch, from };
}

const { target: rawTarget, branch, from } = parseArgs(process.argv.slice(2));

// The repository root of the worktree this script was invoked from. `--git-common-dir` points at
// the shared `.git` even when we are already inside a linked worktree, so this resolves to the
// MAIN worktree in both cases — which is where node_modules and husky live.
const commonDir = path.resolve(git(['rev-parse', '--git-common-dir']));
const mainRoot = path.dirname(commonDir);

// Relative paths resolve against the REPO ROOT, never cwd. This script is invoked as
// `npm run worktree:create` from `server/` (where CONTRIBUTING's Quick Start leaves the reader)
// and directly from the repo root; without this, `../featurex` would name two different
// directories depending on which one you happened to be in.
const target = path.resolve(mainRoot, rawTarget);

if (existsSync(target)) fail(`${target} already exists. Choose another path, or remove it first.`);

const branchExists = (() => {
  try {
    git(['rev-parse', '--verify', '--quiet', `refs/heads/${branch}`]);
    return true;
  } catch {
    return false;
  }
})();

console.log(`\n📁 Creating worktree at ${target}`);
console.log(`   branch ${branch}${branchExists ? ' (existing)' : ` (new, from ${from})`}`);

// `git worktree add` is the only step that touches shared git state, and it neither moves HEAD in
// the current worktree nor reads its working tree — safe to run alongside a concurrent session.
const addArgs = branchExists
  ? ['worktree', 'add', target, branch]
  : ['worktree', 'add', '-b', branch, target, from];
try {
  execFileSync('git', addArgs, { stdio: 'inherit' });
} catch {
  fail('git worktree add failed. Nothing was changed.');
}

console.log('\n🪝 Wiring git hooks (husky)…');
try {
  execFileSync('npx', ['--prefix', mainRoot, 'husky'], { cwd: target, stdio: 'pipe' });
} catch (error) {
  fail(
    'husky did not run. Install dependencies in the main worktree first:\n' +
      `    npm install --prefix ${mainRoot}\n` +
      `  then re-run husky in the new worktree:\n` +
      `    cd ${target} && npx --prefix ${mainRoot} husky\n` +
      `  (${error.message})`
  );
}

// BOTH trees, not just server/. Measured 2026-08-17: linking only `server/node_modules` left
// `commit-msg` failing with "npx canceled due to missing packages [commitlint]" — commitlint is a
// ROOT devDependency, and the hook resolves it from the worktree root. A hook that fires and then
// dies on a missing package is no better than one that never fires.
for (const relative of ['node_modules', path.join('server', 'node_modules')]) {
  const destination = path.join(target, relative);
  if (existsSync(destination)) continue;
  const source = path.join(mainRoot, relative);
  if (!existsSync(source)) {
    console.log(`⚠️  ${relative} is missing in the main worktree — run npm install there`);
    continue;
  }
  symlinkSync(source, destination, 'dir');
  console.log(`📦 Linked ${relative} from the main worktree`);
}

// The linked tree must read as clean. `.gitignore` names `node_modules` WITHOUT a trailing slash
// on purpose: `node_modules/` matches directories only, and the links above are symlinks, so
// with the slash every linked worktree showed `?? node_modules` forever. That is not cosmetic —
// `server/scripts/typecheck-committed.js` short-circuits on `git status --porcelain` being empty,
// so the untracked links disabled its fast path on every push, and `git add -A` would stage an
// absolute-path symlink. Assert it here so a future ignore-rule edit cannot regress it silently.
const dirty = git(['status', '--porcelain'], target);
if (dirty !== '') {
  fail(
    `the new worktree is not clean after bootstrap:\n${dirty}\n` +
      '  Linked node_modules must be ignored (see the `node_modules` patterns in .gitignore —\n' +
      '  no trailing slash, or symlinks are not matched).'
  );
}

// Prove it. An unverified bootstrap is the defect this script exists to fix.
const prePush = path.join(target, '.husky', '_', 'pre-push');
if (!existsSync(prePush)) {
  fail(
    `hooks are still not wired: ${prePush} does not exist.\n` +
      '  Git would skip every hook in this worktree silently, which is exactly the failure this\n' +
      '  script exists to prevent. The worktree was created; fix the hooks before committing.'
  );
}
try {
  accessSync(prePush, constants.X_OK);
} catch {
  fail(`${prePush} exists but is not executable — git will skip it silently.`);
}

console.log('✅ Hooks verified live (.husky/_/pre-push present and executable)');
console.log(`\n   cd ${target}\n`);
